-- Normative PostgreSQL 16 migration. Apply once as migration owner, not runtime role.
BEGIN;
CREATE SCHEMA core;
CREATE SCHEMA afr;
CREATE SCHEMA skb;
CREATE SCHEMA evf;
CREATE TABLE core.organizations(id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120));
CREATE TABLE core.users(id uuid PRIMARY KEY, issuer text NOT NULL, subject text NOT NULL, UNIQUE(issuer,subject));
CREATE TABLE core.memberships(organization_id uuid REFERENCES core.organizations, user_id uuid REFERENCES core.users, org_role text NOT NULL CHECK(org_role IN ('member','admin')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE core.projects(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES core.organizations, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), content_capture text NOT NULL DEFAULT 'metadata_only' CHECK(content_capture IN ('metadata_only','redacted')), external_transfer boolean NOT NULL DEFAULT false, revision bigint NOT NULL DEFAULT 1 CHECK(revision>0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.project_roles(project_id uuid REFERENCES core.projects,user_id uuid REFERENCES core.users, role text NOT NULL CHECK(role IN ('viewer','analyst','operator','maintainer')),PRIMARY KEY(project_id,user_id,role));
CREATE TABLE core.api_keys(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES core.projects,key_digest bytea NOT NULL UNIQUE,scopes text[] NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE core.artifacts(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES core.projects,sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'),byte_size bigint NOT NULL CHECK(byte_size>0 AND byte_size<=104857600),media_type text NOT NULL,classification text NOT NULL CHECK(classification IN ('synthetic','public_authorized','sensitive')),state text NOT NULL CHECK(state IN ('pending','ready','quarantined','deleting','deleted')),storage_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz,UNIQUE(project_id,id));
CREATE TABLE core.uploads(id uuid PRIMARY KEY,project_id uuid NOT NULL,artifact_id uuid NOT NULL,expected_size bigint NOT NULL CHECK(expected_size>0),expected_sha256 text NOT NULL,expires_at timestamptz NOT NULL,finalized_at timestamptz,FOREIGN KEY(project_id,artifact_id) REFERENCES core.artifacts(project_id,id));
CREATE TABLE core.artifact_links(project_id uuid NOT NULL,parent_id uuid NOT NULL,child_id uuid NOT NULL,relation text NOT NULL,PRIMARY KEY(project_id,parent_id,child_id),CHECK(parent_id<>child_id),FOREIGN KEY(project_id,parent_id) REFERENCES core.artifacts(project_id,id),FOREIGN KEY(project_id,child_id) REFERENCES core.artifacts(project_id,id));
CREATE TABLE core.jobs(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES core.projects,kind text NOT NULL,state text NOT NULL CHECK(state IN ('queued','leased','running','cancel_requested','succeeded','failed','timed_out','cancelled','failed_unknown_effect')),payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),attempt integer NOT NULL DEFAULT 0 CHECK(attempt>=0),fence bigint NOT NULL DEFAULT 0,revision bigint NOT NULL DEFAULT 1,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),result_id uuid,error_code text,UNIQUE(project_id,id));
CREATE INDEX jobs_dispatch ON core.jobs(state,created_at) WHERE state IN ('queued','leased','running','cancel_requested');
CREATE TABLE core.job_attempts(project_id uuid NOT NULL,job_id uuid NOT NULL,attempt integer NOT NULL CHECK(attempt>0),fence bigint NOT NULL,state text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,PRIMARY KEY(job_id,attempt),FOREIGN KEY(project_id,job_id) REFERENCES core.jobs(project_id,id));
CREATE TABLE core.idempotency(organization_id uuid REFERENCES core.organizations,project_id uuid REFERENCES core.projects,actor_id uuid NOT NULL,route text NOT NULL,key uuid NOT NULL,request_sha256 text NOT NULL,response_status integer NOT NULL,response_body jsonb NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(actor_id,route,key),CHECK(project_id IS NOT NULL OR organization_id IS NOT NULL));
CREATE TABLE core.outbox(id bigserial PRIMARY KEY,project_id uuid NOT NULL REFERENCES core.projects,kind text NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz);
CREATE TABLE core.budget_reservations(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES core.projects,job_id uuid NOT NULL,token_limit bigint NOT NULL CHECK(token_limit>=0),call_limit integer NOT NULL CHECK(call_limit>=0),reserved_eur numeric(20,8) CHECK(reserved_eur>=0),observed_eur numeric(20,8) CHECK(observed_eur>=0),state text NOT NULL CHECK(state IN ('reserved','settled','unknown','released')),FOREIGN KEY(project_id,job_id) REFERENCES core.jobs(project_id,id));
CREATE TABLE core.audit_events(id bigserial PRIMARY KEY,project_id uuid REFERENCES core.projects,actor_id uuid,action text NOT NULL,target_id uuid,decision text NOT NULL,policy_version text NOT NULL,request_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.deletions(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES core.projects,target_kind text NOT NULL,target_id uuid NOT NULL,state text NOT NULL CHECK(state IN ('requested','revoked','purging','complete','failed')),revoked_at timestamptz NOT NULL,purge_deadline timestamptz NOT NULL,completed_at timestamptz,UNIQUE(project_id,target_kind,target_id));
CREATE TABLE afr.runs(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES core.projects,state text NOT NULL CHECK(state IN ('recording','completed','failed','abandoned')),revision bigint NOT NULL DEFAULT 1,event_count bigint NOT NULL DEFAULT 0,completeness text[] NOT NULL DEFAULT '{}',verified_outcome text NOT NULL DEFAULT 'unscored' CHECK(verified_outcome IN ('unscored','pass','fail','error')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE INDEX runs_inventory ON afr.runs(project_id,created_at DESC,id);
CREATE TABLE afr.events(id uuid NOT NULL,project_id uuid NOT NULL,run_id uuid NOT NULL,producer_id text NOT NULL,producer_seq bigint NOT NULL CHECK(producer_seq>=0),event_type text NOT NULL,observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),payload_sha256 text NOT NULL,envelope jsonb NOT NULL,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id,run_id) REFERENCES afr.runs(project_id,id),UNIQUE(project_id,run_id,producer_id,producer_seq));
CREATE INDEX events_run ON afr.events(project_id,run_id,received_at,id);
CREATE TABLE afr.cases(id uuid PRIMARY KEY,project_id uuid NOT NULL,run_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),run_revision bigint NOT NULL,manifest_sha256 text NOT NULL,definition jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,run_id) REFERENCES afr.runs(project_id,id),UNIQUE(project_id,id));
CREATE TABLE afr.replays(id uuid PRIMARY KEY,project_id uuid NOT NULL,case_id uuid NOT NULL,job_id uuid NOT NULL,mode text NOT NULL CHECK(mode IN ('visual','recorded')),result jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,case_id) REFERENCES afr.cases(project_id,id),FOREIGN KEY(project_id,job_id) REFERENCES core.jobs(project_id,id));
CREATE TABLE skb.packages(id uuid PRIMARY KEY,project_id uuid NOT NULL,artifact_id uuid NOT NULL,sha256 text NOT NULL,state text NOT NULL CHECK(state IN ('quarantined','inspected','approved','rejected')),revision bigint NOT NULL DEFAULT 1,execution_profile text NOT NULL CHECK(execution_profile='fixture_only'),source_commit text,license_expression text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,artifact_id) REFERENCES core.artifacts(project_id,id),UNIQUE(project_id,id));
CREATE TABLE skb.package_reviews(id uuid PRIMARY KEY,project_id uuid NOT NULL,package_id uuid NOT NULL,package_sha256 text NOT NULL,actor_id uuid NOT NULL REFERENCES core.users,decision text NOT NULL CHECK(decision IN ('approved','rejected')),reason text NOT NULL CHECK(length(reason)>=5),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,package_id) REFERENCES skb.packages(project_id,id));
CREATE TABLE skb.suites(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES core.projects,version integer NOT NULL CHECK(version>0),sha256 text NOT NULL,definition jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
-- Candidate-visible fixtures must never contain hidden answers. Secret scorer artifacts use separate collector capabilities; not returned by this API.
CREATE TABLE skb.hidden_answers(id uuid PRIMARY KEY,project_id uuid NOT NULL,suite_id uuid NOT NULL,artifact_id uuid NOT NULL,FOREIGN KEY(project_id,suite_id) REFERENCES skb.suites(project_id,id),FOREIGN KEY(project_id,artifact_id) REFERENCES core.artifacts(project_id,id));
CREATE TABLE skb.plans(id uuid PRIMARY KEY,project_id uuid NOT NULL,package_id uuid NOT NULL,suite_id uuid NOT NULL,sha256 text NOT NULL,state text NOT NULL CHECK(state IN ('draft','preregistered')),revision bigint NOT NULL DEFAULT 1,definition jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,package_id) REFERENCES skb.packages(project_id,id),FOREIGN KEY(project_id,suite_id) REFERENCES skb.suites(project_id,id),UNIQUE(project_id,id));
CREATE TABLE skb.experiments(id uuid PRIMARY KEY,project_id uuid NOT NULL,plan_id uuid NOT NULL,plan_sha256 text NOT NULL,state text NOT NULL CHECK(state IN ('queued','running','completed','stopped','failed')),job_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,plan_id) REFERENCES skb.plans(project_id,id),FOREIGN KEY(project_id,job_id) REFERENCES core.jobs(project_id,id),UNIQUE(project_id,id));
CREATE TABLE skb.trials(id uuid PRIMARY KEY,project_id uuid NOT NULL,experiment_id uuid NOT NULL,task_id text NOT NULL,repeat integer NOT NULL CHECK(repeat>=0),arm text NOT NULL CHECK(arm IN ('baseline','treatment')),attempt integer NOT NULL CHECK(attempt>0),outcome text NOT NULL CHECK(outcome IN ('pass','fail','infra_error','policy_block','activation_failed','cancelled')),cost_eur numeric(20,8) CHECK(cost_eur>=0),result jsonb NOT NULL,FOREIGN KEY(project_id,experiment_id) REFERENCES skb.experiments(project_id,id),UNIQUE(experiment_id,task_id,repeat,arm,attempt));
CREATE TABLE skb.analyses(id uuid PRIMARY KEY,project_id uuid NOT NULL,experiment_id uuid NOT NULL,input_sha256 text NOT NULL,version text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,experiment_id) REFERENCES skb.experiments(project_id,id));
CREATE TABLE evf.documents(id uuid PRIMARY KEY,project_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),source_artifact_id uuid NOT NULL,source_sha256 text NOT NULL,title text NOT NULL,state text NOT NULL CHECK(state IN ('quarantined','accepted','parsing','parsed','partial','failed','deleting')),page_count integer CHECK(page_count BETWEEN 1 AND 100),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,source_artifact_id) REFERENCES core.artifacts(project_id,id),UNIQUE(project_id,id));
CREATE TABLE evf.parses(id uuid PRIMARY KEY,project_id uuid NOT NULL,document_id uuid NOT NULL,source_sha256 text NOT NULL,profile text NOT NULL CHECK(profile IN ('fixture/1','docling_local/1')),profile_sha256 text NOT NULL,state text NOT NULL CHECK(state IN ('queued','running','parsed','partial','failed')),job_id uuid NOT NULL,output_artifact_id uuid,page_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,document_id) REFERENCES evf.documents(project_id,id),FOREIGN KEY(project_id,job_id) REFERENCES core.jobs(project_id,id),FOREIGN KEY(project_id,output_artifact_id) REFERENCES core.artifacts(project_id,id),UNIQUE(project_id,id));
CREATE TABLE evf.elements(project_id uuid NOT NULL,parse_id uuid NOT NULL,element_id text NOT NULL,page_ordinal integer NOT NULL CHECK(page_ordinal>0),kind text NOT NULL,text_content text,geometry jsonb NOT NULL,structure jsonb NOT NULL,PRIMARY KEY(parse_id,element_id),FOREIGN KEY(project_id,parse_id) REFERENCES evf.parses(project_id,id));
CREATE TABLE evf.extractions(id uuid PRIMARY KEY,project_id uuid NOT NULL,parse_id uuid NOT NULL,schema_version text NOT NULL CHECK(schema_version='annual-report-8/1'),revision bigint NOT NULL DEFAULT 1,fields jsonb NOT NULL CHECK(jsonb_typeof(fields)='array' AND jsonb_array_length(fields)=8),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,parse_id) REFERENCES evf.parses(project_id,id),UNIQUE(project_id,id));
CREATE TABLE evf.reviews(id uuid PRIMARY KEY,project_id uuid NOT NULL,extraction_id uuid NOT NULL,revision bigint NOT NULL,base_revision bigint NOT NULL,actor_id uuid NOT NULL REFERENCES core.users,patches jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(revision=base_revision+1),FOREIGN KEY(project_id,extraction_id) REFERENCES evf.extractions(project_id,id),UNIQUE(extraction_id,revision));
CREATE TABLE evf.exports(id uuid PRIMARY KEY,project_id uuid NOT NULL,extraction_id uuid NOT NULL,review_revision bigint NOT NULL,artifact_id uuid NOT NULL,manifest_sha256 text NOT NULL,incomplete boolean NOT NULL,warnings jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,extraction_id) REFERENCES evf.extractions(project_id,id),FOREIGN KEY(project_id,artifact_id) REFERENCES core.artifacts(project_id,id));
-- Runtime cannot rewrite immutable evidence. Deletion uses separate lifecycle role.
CREATE FUNCTION core.prevent_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable_record' USING ERRCODE='23000'; END $$;
CREATE TRIGGER no_event_mutation BEFORE UPDATE ON afr.events FOR EACH ROW EXECUTE FUNCTION core.prevent_mutation();
CREATE TRIGGER no_case_mutation BEFORE UPDATE ON afr.cases FOR EACH ROW EXECUTE FUNCTION core.prevent_mutation();
CREATE TRIGGER no_review_mutation BEFORE UPDATE ON evf.reviews FOR EACH ROW EXECUTE FUNCTION core.prevent_mutation();
CREATE TRIGGER no_analysis_mutation BEFORE UPDATE ON skb.analyses FOR EACH ROW EXECUTE FUNCTION core.prevent_mutation();
CREATE TRIGGER no_audit_mutation BEFORE UPDATE OR DELETE ON core.audit_events FOR EACH ROW EXECUTE FUNCTION core.prevent_mutation();
CREATE FUNCTION skb.freeze_plan() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.state='preregistered' THEN RAISE EXCEPTION 'preregistered_plan_immutable' USING ERRCODE='23000'; END IF; RETURN NEW; END $$;
CREATE TRIGGER freeze_plan BEFORE UPDATE ON skb.plans FOR EACH ROW EXECUTE FUNCTION skb.freeze_plan();
-- Roles are granted narrowly by 002_roles.sql; app is not table owner or migration role.
COMMIT;
